    assurance:{browser:'Read in-browser',zero:'Zero fabrication',provenance:'Cell-by-cell provenance',blind:'Double-blind matching'},
    status:{verified:'Verified',review:'Review'},
    proof:{note1:'EU HOSTED · GDPR READY',note2:'ZERO FABRICATION · 256-BIT ENCRYPTION',oneTitle:'Institutional teasers',oneBody:'Ready for the investment committee',twoTitle:'Traceable intelligence',twoBody:'Auditable from source to output',threeTitle:'Anonymous connection',threeBody:'Double-blind before identity'},
    statement:{kicker:'THE MARKET PROBLEM',title:'The asset may be real.<br><em>The signal is still scattered.</em>',body:'An IM, PDF files, a financial model, broker notes, images, emails and conversations. Before an opportunity can be presented with confidence, someone has to bring the evidence together, check every figure and decide what the other side is allowed to see.',punch:'The problem is not a lack of information. It is a lack of structure, traceability and fit.'},
    walkthrough:{kicker:'THE LOPTOR METHOD',title:'From scattered files<br><em>to a defensible teaser.</em>',intro:'See how an opportunity moves from a messy file set to an institutional presentation without losing the relationship between a claim and its source.',demoLabel:'FICTIONAL WORKSPACE · NO PRODUCTION DATA'},
    seller:{kicker:'FOR THE SELL-SIDE',title:'Present the asset<br><em>without overexposing it.</em>',body:'A good teaser is not the one that says the most. It is the one that shows enough to create interest while keeping control of what remains to be verified or requested.',feature1Title:'The living dossier',feature1Body:'Keep the asset’s sources, coverage and evolution together.',feature2Title:'Selective visibility',feature2Body:'Issue a text-only, one-photo or gallery teaser.',feature3Title:'Anonymity checks',feature3Body:'Flag signs that could reveal the asset too early.',cta:'Request a demo <span>↗</span>'},
    buyer:{kicker:'FOR THE BUY-SIDE',title:'Let your mandate<br><em>work quietly.</em>',body:'Define what you are looking for, where, at what ticket and with which exclusions. LoptorCRE watches the market in the background and alerts you when a fit appears.',punch:'You do not need a catalogue of assets. You need the opportunities that meet your mandate.',cta:'Request a demo <span>↗</span>'},
    shots:{note:'Real app screens · fictional data'},
    matching:{kicker:'HOW THE MATCH WORKS',title:'A match you can explain,<br><em>not a black box.</em>',rt:'The radar, working in the background',rb:'The radar crosses the assets and mandates that each side has authorised for blind matching. It only surfaces matches that reach 85% True Fit, and it shows the zone, never the address.',intro:'AI helps structure your documents. The match itself is calculated by transparent rules, so the same asset and the same mandate always produce the same result.',s1t:'Hard filters first',s1b:'Asset type, ticket range, authorisation from both parties and the buyer’s exclusions. If one fails, there is no match.',s2t:'Only documented data',s2b:'The score reads what is documented and sourced in the dossier. What is missing adds nothing: the engine never estimates a figure.',s3t:'A True Fit score',s3b:'Each criterion the mandate declares is weighted. A match is proposed from 85% True Fit.',s4t:'Identity later',s4b:'Both sides see an anonymous spec sheet. Names and contacts are released only when both approve.'},
    privacy:{kicker:'YOUR INFORMATION',title:'Your information is yours.<br><em>Until you decide to share it.</em>',t1:'Never used to train AI',b1:'Nothing you upload or write is used to train AI models.',t2:'Only you can access it',b2:'Your dossier is private. Only you can see it before you share it.',t3:'Loptor can’t see it either',b3:'Loptor does not access your information. Only what you choose to share leaves your workspace, and it goes anonymised.'},
    darkpool:{kicker:'THE DARK POOL',title:'The liquidity that<br><em>doesn’t appear in a catalogue.</em>',body:'Some assets should not be published. Some buyers do not want to announce themselves. LoptorCRE creates the point of connection without sacrificing the confidentiality of the process.',principle:'Fit first. Identity later.',lock:'Identity protected until consent'},
    portfolio:{kicker:'FOR THE WHOLE PORTFOLIO',title:'From one asset<br><em>to a clearer portfolio.</em>',body:'When opportunities multiply, you need to know what is documented, what is ready to present and where new connections are forming.',illustrative:'Illustrative example'},
    trust:{kicker:'RADICAL TRANSPARENCY',title:'Built to structure and connect.<br><em>Not to promise everything.</em>',intro:'Trust also means explaining the limits of the product.',yesTitle:'LoptorCRE is',yes1:'An analytical structuring engine for scattered documents.',yes2:'An institutional A4 teaser generator with selective visibility.',yes3:'An anonymous matching layer for financial and operational parameters.',yes4:'A documentary certainty audit with zero fabrication.',noTitle:'LoptorCRE is not',no1:'A VDR for storing a complete due diligence.',no2:'A service for NDAs or electronic signatures.',no3:'An open commercial catalogue of assets or buyers.',no4:'A place to share full files before consent.'},
    pricing:{kicker:'PLANS BY TEAM SIZE',title:'Start at the level<br><em>you need today.</em>',intro:'From an independent broker to a transaction team, a fund or a large portfolio, LoptorCRE grows with the assets, users and mandates you coordinate. Pricing is shared in a short demo.',note:'Request a demo · 14-day free trial on every plan · no card required'},
    beta:{kicker:'THE BETA',title:'The beta starts with<br><em>what matters most.</em>',body:'The first version focuses on structuring dossiers, controlling visibility, issuing institutional teasers and finding anonymous fits. Collaboration and secure sharing will expand progressively.',cta:'Read the product boundaries <span>↓</span>',liveLabel:'LIVE IN BETA',liveTitle:'Evidence-led foundation',live1:'Provenance and conflicts',live2:'Three teaser visibility levels',live3:'Mandates, Dark Pool, Deal Rooms and portfolio overview',live4:'Bilingual ES / EN experience',live5:'Traceable sharing link with expiry',nextLabel:'IN DEVELOPMENT',nextTitle:'Secure collaboration',next1:'Secure sharing link',next2:'Blind chat inside the Deal Room',next3:'Meeting mode and operation roles',next4:'French experience',next5:'Cross-firm anonymous matching'},
