function planCell(value, t) {
  if (value === true) return `<span class="cmp-yes" aria-hidden="true">✓</span><span class="vh">${t.yes}</span>`;
  if (value === false) return `<span class="cmp-no" aria-hidden="true">—</span><span class="vh">${t.no}</span>`;
  return value;
}
function renderPlanCards(lang) {
  const c = PLAN_COPY[lang] || PLAN_COPY.en;
  return c.cards.map((card, i) => {
    const key = PLAN_KEYS[i];
    const featured = key === 'desk';
    const stats = card.stats
      ? `<div class="plan-stats">${card.stats.map(([n, l]) => `<div><strong>${n === '∞' ? `<span aria-hidden="true">∞</span><span class="vh">${c.unlimited}</span>` : n}</strong><small>${l}</small></div>`).join('')}</div>`
      : `<p class="plan-tailored">${card.tailored}</p>`;
    return `<article class="price-card${featured ? ' is-featured' : ''}">${featured ? `<div class="featured-tag">${c.recommended}</div>` : ''}<div class="price-label">0${i + 1} / ${card.name}</div><h3>${PLAN_NAMES[key]}</h3><p>${card.desc}</p><div class="plan-billing">${card.billing}</div>${stats}<a class="button ${featured ? 'button-primary' : 'button-outline'} price-cta" data-demo data-plan="${key}" href="${demoHref(lang, key)}">${c.cta} <span>↗</span></a><ul>${card.base ? `<li class="plan-base">${card.base}</li>` : ''}${card.bullets.map((b) => `<li>${b}</li>`).join('')}</ul></article>`;
  }).join('');
}
function renderPlanCompare(lang) {
  const c = PLAN_COPY[lang] || PLAN_COPY.en;
  const t = c.table;
  const head = c.cards.map((card, i) => {
    const key = PLAN_KEYS[i];
    const featured = key === 'desk';
    return `<th scope="col" class="cmp-plan${featured ? ' is-featured' : ''}">${featured ? `<span class="cmp-tag">${c.recommended}</span>` : ''}<span class="cmp-plan-name">${PLAN_NAMES[key]}</span><span class="cmp-plan-for">${card.name}</span><a class="button ${featured ? 'button-primary' : 'button-outline'} cmp-cta" data-demo data-plan="${key}" href="${demoHref(lang, key)}">${c.cta}</a></th>`;
  }).join('');
  const body = t.groups.map((g) => `<tr class="cmp-group"><th scope="colgroup" colspan="5">${g.title}</th></tr>${g.rows.map((row) => `<tr><th scope="row">${row[0]}</th>${row.slice(1).map((v, i) => `<td${i === 1 ? ' class="is-featured"' : ''}>${planCell(v, t)}</td>`).join('')}</tr>`).join('')}`).join('');
  return `<div class="plan-compare-head"><h3>${t.title}</h3><p>${t.intro}</p></div><div class="cmp-scroll" role="region" aria-label="${t.caption}" tabindex="0"><table class="cmp-table"><caption class="vh">${t.caption}</caption><thead><tr><th scope="col" class="cmp-feature-col">${t.feature}</th>${head}</tr></thead><tbody>${body}</tbody></table></div><p class="cmp-note">${t.note}</p>`;
}
/*PLANS-END*/

let currentLang = 'en';
let currentStep = 0;
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const get = (path) => path.split('.').reduce((obj, key) => obj?.[key], I18N[currentLang]);

function applyTranslations() {
  const locale = I18N[currentLang];
  document.documentElement.lang = currentLang;
  $$('[data-i18n]').forEach((el) => {
    const value = get(el.dataset.i18n);
    if (value !== undefined) el.innerHTML = value;
  });
  const navMap = { '.main-nav a[href="#walkthrough"]':'nav.how', '.main-nav a[href="#matching"]':'nav.match', '.main-nav a[href="#privacy"]':'nav.data', '.footer-links a[href="#walkthrough"]':'nav.how', '.main-nav a[href="#dark-pool"]':'nav.dark', '.main-nav a[href="#pricing"]':'nav.pricing', '.main-nav a[href="#faq"]':'nav.faq', '.header-login':'nav.login', '.button-small':'nav.trial' };
  Object.entries(navMap).forEach(([selector, path]) => { const el = $(selector); if (el) el.innerHTML = get(path); });
  $$('.step-button').forEach((button, index) => {
    button.querySelector('[data-step-title]').textContent = locale.steps[index].title;
    button.querySelector('[data-step-short]').textContent = locale.steps[index].short;
  });
  if (locale.meta) {
    document.title = locale.meta.title;
    const md = document.querySelector('meta[name="description"]'); if (md) md.setAttribute('content', locale.meta.desc);
  }
  renderWalkthrough();
  renderFaq();
  renderPlans();
  localizeStaticUi();
  updateAppLinks();
}

function updateAppLinks() {
  $$('a[href^="https://app.loptorcre.com/"]').forEach((link) => {
    const url = new URL(link.href);
    const action = url.searchParams.get('action');
    if (action === 'login' || action === 'register') {
      url.searchParams.set('lang', currentLang);
      link.href = url.toString();
    }
  });
}

function renderWalkthrough() {
  const locale = I18N[currentLang];
  $('#stage-content').innerHTML = demoTemplates[currentStep];
  localizeDemoStage();
  $('#step-name').textContent = locale.steps[currentStep].title;
  $('#stage-description').textContent = locale.steps[currentStep].description;
  $('#step-current').textContent = String(currentStep + 1).padStart(2, '0');
  $$('.step-button').forEach((button, index) => { const active = index === currentStep; button.classList.toggle('is-active', active); button.setAttribute('aria-selected', String(active)); });
  const prev = $('#step-prev'); const next = $('#step-next');
  prev.disabled = currentStep === 0; next.disabled = currentStep === locale.steps.length - 1;
  prev.style.opacity = prev.disabled ? '.35' : '1'; next.style.opacity = next.disabled ? '.35' : '1';
}

function renderFaq() {
  const list = $('#faq-list');
  if (!list) return;
  let n = 0;
  list.innerHTML = I18N[currentLang].faqGroups.map(([group, items]) => `<div class="faq-group"><h3 class="faq-group-title">${group}</h3>${items.map(([question, answer]) => { n += 1; const id = 'faq-' + n; return `<div class="faq-item"><h4 class="faq-q"><button type="button" class="faq-btn" aria-expanded="false" aria-controls="${id}"><span class="faq-num" aria-hidden="true">${String(n).padStart(2, '0')}</span><span class="faq-text">${question}</span><span class="faq-icon" aria-hidden="true"></span></button></h4><div class="faq-panel" id="${id}" role="region"><div><p>${answer}</p></div></div></div>`; }).join('')}</div>`).join('');
  $$('.faq-btn', list).forEach((button) => button.addEventListener('click', () => {
    const item = button.closest('.faq-item');
    const open = !item.classList.contains('is-open');
    $$('.faq-item.is-open', list).forEach((other) => { other.classList.remove('is-open'); other.querySelector('.faq-btn').setAttribute('aria-expanded', 'false'); });
    item.classList.toggle('is-open', open);
    button.setAttribute('aria-expanded', String(open));
  }));
}

function renderPlans() {
  const cards = $('#plan-cards'); const compare = $('#plan-compare');
  if (cards) cards.innerHTML = renderPlanCards(currentLang);
  if (compare) compare.innerHTML = renderPlanCompare(currentLang);
  $$('[data-demo]').forEach((el) => { el.href = DEMO_URL; el.target = '_blank'; el.rel = 'noopener'; });
}

function setLanguage(lang) { if (!I18N[lang]) return; currentLang = lang; $$('.lang-btn').forEach((button) => button.classList.toggle('is-active', button.dataset.lang === lang)); applyTranslations(); try { localStorage.setItem('loptor-lang', lang); } catch (_) {} }


// Calendario de demos (Cal.com) integrado en una ventana emergente. El script de Cal.com
// no se carga con la página: solo cuando alguien pulsa un botón de demo. Si no carga
// (bloqueador, red), el enlace normal se abre en una pestaña nueva.
const CAL_LINK = 'loptorcre/30min';
let calState = 'idle'; // idle | loading | ready | failed
let calPlan = '';
function loadCal() {
  if (calState !== 'idle') return;
  calState = 'loading';
  (function (C, A, L) { const p = function (a, ar) { a.q.push(ar); }; const d = C.document; C.Cal = C.Cal || function () { const cal = C.Cal; const ar = arguments; if (!cal.loaded) { cal.ns = {}; cal.q = cal.q || []; const s = d.createElement('script'); s.src = A; s.async = true; s.onload = () => { calState = 'ready'; }; s.onerror = () => { calState = 'failed'; }; d.head.appendChild(s); cal.loaded = true; } if (ar[0] === L) { const api = function () { p(api, arguments); }; const ns = ar[1]; api.q = api.q || []; if (typeof ns === 'string') { cal.ns[ns] = cal.ns[ns] || api; p(cal.ns[ns], ar); p(cal, ['initNamespace', ns]); } else p(cal, ar); return; } p(cal, ar); }; })(window, 'https://app.cal.com/embed/embed.js', 'init');
  window.Cal('init', { origin: 'https://app.cal.com' });
  window.Cal('on', { action: 'bookingSuccessful', callback: () => { if (window.loptorTrack) window.loptorTrack('demo_booked', { lang: currentLang, plan: calPlan }); } });
}
function openCal(plan) {
  loadCal();
  calPlan = plan || '';
  const config = { layout: 'month_view' };
  const notes = [];
  if (plan && PLAN_NAMES[plan]) notes.push(`Plan: ${PLAN_NAMES[plan]}`);
  notes.push(`Web language: ${currentLang.toUpperCase()}`);
  config.notes = notes.join(' · ');
  window.Cal('modal', { calLink: CAL_LINK, config });
  setTimeout(() => { if (calState !== 'ready') window.open(DEMO_URL, '_blank', 'noopener'); }, 5000);
}
document.addEventListener('click', (event) => {
  const link = event.target && event.target.closest ? event.target.closest('a[data-demo]') : null;
  if (!link || event.metaKey || event.ctrlKey || event.shiftKey || event.button === 1) return;
  if (calState === 'failed') return; // deja que el enlace normal haga su trabajo
  event.preventDefault();
  openCal(link.dataset.plan);
});

function wireEvents() {
  $$('.lang-btn').forEach((button) => button.addEventListener('click', () => setLanguage(button.dataset.lang)));
  $$('.step-button').forEach((button) => button.addEventListener('click', () => { currentStep = Number(button.dataset.step); renderWalkthrough(); }));
  $('#step-prev').addEventListener('click', () => { if (currentStep > 0) { currentStep -= 1; renderWalkthrough(); } });
  $('#step-next').addEventListener('click', () => { if (currentStep < 5) { currentStep += 1; renderWalkthrough(); } });
  const menu = $('.mobile-menu'); const nav = $('.main-nav');
  $('.brand').addEventListener('click', (event) => { event.preventDefault(); nav.classList.remove('is-open'); menu.setAttribute('aria-expanded','false'); window.scrollTo({ top: 0, behavior: 'smooth' }); if (location.hash) history.replaceState(null, '', location.pathname + location.search); });
  menu.addEventListener('click', () => { const open = nav.classList.toggle('is-open'); menu.setAttribute('aria-expanded', String(open)); });
  $$('.main-nav a').forEach((link) => link.addEventListener('click', () => { nav.classList.remove('is-open'); menu.setAttribute('aria-expanded','false'); }));
}

try {
  const requestedLang = new URLSearchParams(window.location.search).get('lang');
  const saved = localStorage.getItem('loptor-lang');
  if (requestedLang && I18N[requestedLang]) {
    currentLang = requestedLang;
    localStorage.setItem('loptor-lang', requestedLang);
  } else if (saved && I18N[saved]) {
    currentLang = saved;
  }
} catch (_) {}
wireEvents();
$$('.lang-btn').forEach((button) => button.classList.toggle('is-active', button.dataset.lang === currentLang));
applyTranslations();

// Anchor navigation: land on the section's content, not on its empty top padding.
(function anchorOffset() {
  const header = document.querySelector('.site-header');
  const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  function go(hash, smooth) {
    if (!hash || hash === '#' || hash === '#top') return false;
    let target = null;
    try { target = document.querySelector(hash); } catch (_) {}
    if (!target) return false;
    let pad = parseFloat(getComputedStyle(target).paddingTop) || 0;
    if (!pad && target.firstElementChild) pad = parseFloat(getComputedStyle(target.firstElementChild).paddingTop) || 0;
    const headerH = header ? header.offsetHeight : 0;
    const top = target.getBoundingClientRect().top + window.scrollY + pad - headerH - 28;
    window.scrollTo({ top: Math.max(0, top), behavior: smooth && !reduce ? 'smooth' : 'auto' });
    return true;
  }
  document.addEventListener('click', (e) => {
    const a = e.target.closest && e.target.closest('a[href^="#"]');
    if (!a) return;
    if (go(a.getAttribute('href'), true)) {
      e.preventDefault();
      try { history.pushState(null, '', a.getAttribute('href')); } catch (_) {}
    }
  });
  if (location.hash) window.addEventListener('load', () => setTimeout(() => go(location.hash, false), 50));
})();

/* Hero: las imágenes miden lo mismo que el texto (de la etiqueta al borde inferior de los botones) */
(function () {
  const prod = document.querySelector('.hero-product.shots');
  const copy = document.querySelector('.hero-copy');
  if (!prod || !copy) return;
  const RATIO = 1273 / 900; // alto / ancho del teaser A4
  const mq = window.matchMedia('(min-width:1101px)');
  const VARS = ['--hp-h', '--hp-bh', '--hp-th', '--hp-total'];
  const GAP = 14;
  const BANNER = 172 / 1400; // alto / ancho de la franja de cifras
  const COVER = 1120 / 1100; // alto / ancho de la portada recortada
  function layout() {
    if (!mq.matches) { VARS.forEach((v) => prod.style.removeProperty(v)); return; }
    const eyebrow = copy.querySelector('.eyebrow');
    const button = copy.querySelector('.hero-actions .button');
    if (!eyebrow || !button) return;
    const H = button.getBoundingClientRect().bottom - eyebrow.getBoundingClientRect().top;
    const W = prod.clientWidth;
    if (!(H > 0) || !(W > 0)) return;
    // franja de cifras arriba y la portada del teaser debajo, del mismo ancho; todo mide lo que el texto
    let w = (H - GAP) / (BANNER + COVER);
    w = Math.min(w, W);
    const th = w * COVER;
    const bh = w * BANNER;
    prod.style.setProperty('--hp-bh', bh + 'px');
    prod.style.setProperty('--hp-th', th + 'px');
    prod.style.setProperty('--hp-total', w + 'px');
    prod.style.setProperty('--hp-h', (bh + GAP + th) + 'px');
  }
  let raf = 0;
  const schedule = () => { cancelAnimationFrame(raf); raf = requestAnimationFrame(layout); };
  window.addEventListener('resize', schedule);
  window.addEventListener('load', schedule);
  if (mq.addEventListener) mq.addEventListener('change', schedule);
  if (window.ResizeObserver) new ResizeObserver(schedule).observe(copy);
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(schedule);
  schedule();
})();
